{"path": "/tmp/sv-73824bbb5da04a79964e60b619acc72d/wwwroot/js/chat-scroll.js", "file_text": "let observer = null;

export function observeScrollSentinel(sentinelElement, dotNetRef) {
    if (observer) {
        observer.disconnect();
    }
    observer = new IntersectionObserver(entries => {
        if (entries[0].isIntersecting) {
            dotNetRef.invokeMethodAsync('LoadMoreMessages');
        }
    }, { threshold: 0.1 });
    observer.observe(sentinelElement);
}

export function scrollToBottom(element) {
    if (element) {
        element.scrollTop = element.scrollHeight;
    }
}

export function dispose() {
    if (observer) {
        observer.disconnect();
        observer = null;
    }
}
"}

