    flex-direction: column;
    min-width: 0;
    background: #fff;
}

.chat-thread {
    flex: 0 0 25%;
    min-width: 280px;
    max-width: 420px;
}

.channel-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
    background: #fff;
}

.channel-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #1d1c1d;
}

.channel-header p {
    margin: 0.15rem 0 0;
    font-size: 0.8rem;
    color: #888;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
}

.scroll-sentinel {
    height: 1px;
}

.loading-indicator {
    text-align: center;
